import{_ as t,d as o,e as n,x as i}from"./chunks/framework.BRr8VP3a.js";const h=JSON.parse('{"title":"A.3 HV03 Orientation Anchor (Full Interface Card)","description":"","frontmatter":{"title":"A.3 HV03 Orientation Anchor (Full Interface Card)","xkChars":0,"xkWords":1125},"headers":[],"relativePath":"en/theory/appendix-a/a-03.md","filePath":"en/theory/appendix-a/a-03.md"}'),r={name:"en/theory/appendix-a/a-03.md"};function a(d,e,s,c,l,p){return o(),n("div",null,[...e[0]||(e[0]=[i('<div class="theory-source"><h1 id="section-a-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.3</span><span class="xk-num__gap"></span></span>HV03 Orientation Anchor (Full Interface Card) <a class="header-anchor" href="#section-a-3" aria-label="Permalink to &quot;A.3 HV03 Orientation Anchor (Full Interface Card) {#section-a-3}&quot;">​</a></h1><p>A. Identity, Proposition, and Scope</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Interface ID (<code>id</code>)</td><td>HV03</td></tr><tr><td>Qualified ID (<code>qualified_id</code>)</td><td><code>human_variable:HV03</code></td></tr><tr><td>Name (<code>name</code>)</td><td>Orientation Anchor</td></tr><tr><td>Claim type (<code>claim_type</code>)</td><td>H</td></tr><tr><td>Contract role (<code>contract_role</code>)</td><td><code>human_variable_interface</code></td></tr><tr><td>Proposition (<code>proposition</code>)</td><td>A goal, identity, memory, commitment, fear, or common problem may first be registered as candidate material about meaning. Register a conditionally effective orientation anchor within the scope of the instance only if an H1-instance provides support on the preselected outcome for resource allocation, action choice, or coordination.</td></tr><tr><td>Scope (<code>scope</code>)</td><td>Human structures involving intentionality, coordination, or common problems</td></tr><tr><td>Conditions for suspension (<code>pause_condition</code>)</td><td>Do not register a conditionally effective orientation anchor under R1 when there are only slogans, an interpreter’s projections, or coerced uniformity of expression. Sourced expressions, diverse expressions, and risks of coercion may still be registered under R0. Do not infer a common will from them.</td></tr></tbody></table></div><p>B. Formal Dependencies and Limits on Conclusions</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Inferential dependencies (<code>inferential_requires</code>)</td><td>1. <code>human_variable:HV01</code></td></tr><tr><td>Protocol dependencies (<code>protocol_requires</code>)</td><td>1. E2<br>2. EVIDENCE<br>3. SOURCE</td></tr><tr><td>Qualification/specialization (<code>specializes</code>)</td><td>None (empty set)</td></tr><tr><td>References to applicable objects (<code>applies_to</code>)</td><td>None (empty set)</td></tr><tr><td>Conditional support routes (<code>conditional_support_routes</code>)</td><td>1. route_id=HV03-R0-candidate-anchor;<br>claim_level=candidate_description;<br>when=A goal, identity, memory, commitment, fear, or common problem has traceable ways of being expressed and carried, but there is not yet an eligible H1-instance;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Register candidate material about meaning, diverse expressions, disputes over representativeness, and the need for further H1 evidence;<br>result_ceiling=Candidate expressions of meaning only. Do not call them an effective orientation anchor or a common will.<br>2. route_id=HV03-R1-effective-anchor;<br>claim_level=conditional_effect;<br>when=A pre-registered H1-instance returns supported on the single criterion selected in advance among resource allocation, action choice, and coordination outcomes;<br>additional_inferential_requires=H1-instance;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register a conditionally effective orientation anchor within the instance, outcome family, scale, and window;<br>result_ceiling=Do not extrapolate to unselected resource, action, or coordination outcomes. Do not infer genuine consent or a unified inner state, or treat the result as grounds for imposing uniformity of meaning.</td></tr><tr><td>Permitted inferences (<code>allowed_inference</code>)</td><td>1. Conditional directions of coordination and anchors of conflict</td></tr><tr><td>Prohibited leaps (<code>prohibited_leap</code>)</td><td>1. Attributing a unified inner state to a group<br>2. Equating shared language with genuine consent<br>3. Assuming the goal is normatively justified</td></tr></tbody></table></div><p>C. Nine-Axis Scale and Object Contract</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Nine-axis scale profile (<code>scale_profile</code>)</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A=Aggregation level covers individual expressions or actions, cases of particular subjects, the population of potential participants, distributions of stances, and aggregation rules. X=Spatial extent covers sites of relationships, organizational spaces, digital public spaces, and the reach of propagation across domains. T=Time span covers the window from expression to action, cycles of commitment, and lags in drift and decoupling. O=Organizational level covers roles in action, teams, organizations, institutions, and public governance ecologies. C=Causal level covers events of expression, mechanisms of interaction between meaning and action, meso-level coordination structures, institutional arrangements, and systemic conditions. R=Resolution covers original expressions and actions, event sequences, individual cases, distributions of stances, coordination metrics, and summaries. Record compression loss as well. I=Scope of influence covers direct participants, dissenters, indirectly affected people, second-order consequences for coordination, and impacts across domains and generations. N=Network topology scope covers propagation of expressions, links for coordination, heterogeneous clusters, and bridging nodes. J=Scope of jurisdiction and authorization requires separate authorization records for naming the anchor, adopting a judgment of representativeness, and requiring coordination or uniformity. Diverse anchors must be preserved</td></tr><tr><td>Effective object (<code>effective_object</code>)</td><td>A goal, identity, memory, commitment, fear, or common problem that may change resource allocation, action choice, or coordination outcomes</td></tr><tr><td>Scale invariants (<code>scale_invariants</code>)</td><td>1. The bridge from meaning to the preselected resource allocation, action choice, or coordination outcome</td></tr><tr><td>Required additions for scale elevation (<code>required_scale_additions</code>)</td><td>1. Rules of representation<br>2. Heterogeneity<br>3. Distribution of costs and benefits<br>4. J axis</td></tr><tr><td>What changes with scale (<code>changing_semantics</code>)</td><td>1. The content and strength of an anchor and the subjects who carry it can change</td></tr><tr><td>Inapplicable objects (<code>non_applicable_objects</code>)</td><td>1. Nonhuman systems without intentionality, meaning, or capability for commitment</td></tr><tr><td>Prohibited elevations (<code>forbidden_elevation</code>)</td><td>1. Treating local expression directly as a common will</td></tr></tbody></table></div><p>D. State, Evidence, and Variable Flows</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>State set (<code>state</code>)</td><td>1. Dispersed<br>2. Coalescing<br>3. Competing<br>4. Solidified<br>5. Decoupled</td></tr><tr><td>Observables (<code>observables</code>)</td><td>1. Differences in resource allocation before and after the pre-registered expression of meaning appears<br>2. Changes in action choices, rates of completion in collaboration, or conflict patterns<br>3. Acceptance, rejection, and alternative expressions of the anchor at different positions<br>4. Whether the outcome difference under the comparison conditions exceeds the predetermined threshold</td></tr><tr><td>Evidence requirements (<code>evidence</code>)</td><td>1. Resource adjustments<br>2. Sequences of action<br>3. Commitment and exit records<br>4. Evidence of conflict</td></tr><tr><td>Input dependencies and interface content (<code>input_dependencies</code>)</td><td>1. Positions of participation. 2. Safety of expression. 3. Data on resources and actions</td></tr><tr><td>Output effects and variable flows (<code>output_effects</code>)</td><td>1. Generative events. 2. Mobilization of uptake. 3. Agendas for normative choice</td></tr><tr><td>Time window and lag (<code>time_window_and_lag</code>)</td><td>Distinguish short-term slogans, long-term commitments, and intergenerational memory</td></tr><tr><td>Uncertainty (<code>uncertainty</code>)</td><td>Record silence, coerced agreement, and internal heterogeneity</td></tr><tr><td>Local exclusion zone (<code>local_exclusion_zone</code>)</td><td>Aggregation must not erase different goals at positions where people have limited safety</td></tr><tr><td>Affected positions (<code>affected_positions</code>)</td><td>1. People who identify with the anchor<br>2. Dissenters<br>3. People represented<br>4. Cost bearers</td></tr></tbody></table></div><p>E. Uptake, Responsibility, Normative Status, Ceilings, and Correction</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Uptake carriers (<code>carrier</code>)</td><td>1. Narratives<br>2. Commitments<br>3. Shared memory<br>4. Institutional goals<br>5. Problem definitions</td></tr><tr><td>Responsible parties (<code>responsible_subject</code>)</td><td>1. Those making claims of representativeness. 2. Those allocating resources on that basis</td></tr><tr><td>Normative status (<code>normative_status</code>)</td><td>Existence of an anchor does not establish that it is normatively justified</td></tr><tr><td>Judgment ceiling (<code>judgment_ceiling</code>)</td><td>Limit R0 and R1 separately. R0 only describes candidate expressions of meaning. When the corresponding H1-instance supports the effect on the selected outcome, R1 may explain a conditional anchor within a limited scope. Do not extrapolate to unselected outcomes</td></tr><tr><td>Action ceiling (<code>action_ceiling</code>)</td><td>This variable produces only descriptions of candidate anchors, diverse expressions, comparison results, and needs for more evidence. It does not authorize unifying meaning, representing others’ wishes, or coordinating action. Any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures</td></tr><tr><td>Counterexamples (<code>counterexamples</code>)</td><td>1. A repeated slogan does not change any allocation of resources or action<br>2. Uniform expressions under high pressure conceal genuine goals that conflict</td></tr><tr><td>Appeal (<code>appeal</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, members can contest representativeness, submit different goals, or refuse to be anchored through a safe, accessible channel with anti-retaliation protection. This triggers review independent of the original chain of judgment about the anchor</td></tr><tr><td>Rollback (<code>rollback</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, once rollback is authorized, the designated responsible party must within the stated deadline actually revoke the naming of the anchor, remove its force as a representation and its downstream effect on coordination, and restore the state of diverse expression. Preserve versions and verification of completion</td></tr></tbody></table></div></div>',1)])])}const u=t(r,[["render",a]]);export{h as __pageData,u as default};
